{
 "statements": [
  {
   "id": "3.5.1a",
   "type": "FACT",
   "force": null,
   "force_from": null,
   "text": "FACT a driver towing a trailer cannot accelerate as quickly as a driver without a trailer",
   "sources": [
    {
     "id": "m82",
     "quote": "You cannot accelerate as quickly when you are towing a trailer."
    }
   ],
   "flags": [],
   "links": [],
   "note": null
  },
  {
   "id": "3.5.1b",
   "type": "FACT",
   "force": null,
   "force_from": null,
   "text": "FACT a driver towing a trailer needs more space than a driver without a trailer BECAUSE the length of the vehicle is much longer with a trailer attached",
   "sources": [
    {
     "id": "m82",
     "quote": "You also need more space because the length of your vehicle is much longer with a trailer attached."
    }
   ],
   "flags": [],
   "links": [],
   "note": null
  },
  {
   "id": "3.5.1c",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "imperative (\"make sure\")",
   "text": "a driver towing a trailer SHOULD make sure the driver has [?enough] time and room to complete the pass WHEN the driver is about to pass a vehicle",
   "sources": [
    {
     "id": "m82",
     "quote": "Before you pass, make sure you have enough time and room to complete the pass."
    }
   ],
   "flags": [
    {
     "code": "J",
     "span": "enough",
     "note": "No measure of time or space is given."
    }
   ],
   "links": [],
   "note": null
  },
  {
   "id": "3.5.1d",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "imperative (\"allow\")",
   "text": "a driver towing a trailer SHOULD allow [?more] room WHEN the driver has passed a vehicle UNTIL the driver moves back to the original lane",
   "sources": [
    {
     "id": "m82",
     "quote": "Once you have passed, allow more room before you move back to your lane."
    }
   ],
   "flags": [
    {
     "code": "J",
     "span": "more",
     "note": "No specific distance is given for how much more room is needed."
    }
   ],
   "links": [],
   "note": null
  },
  {
   "id": "3.5.1e",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "imperative (\"Do not\")",
   "text": "a driver towing a trailer SHOULD NOT cut back into the original lane [?too soon] WHEN the driver has passed a vehicle BECAUSE it can cause the trailer to sway and make it difficult to control",
   "sources": [
    {
     "id": "m82",
     "quote": "Do not cut back into the lane too soon. This can cause your trailer to sway and make it difficult to control."
    }
   ],
   "flags": [
    {
     "code": "J",
     "span": "too soon",
     "note": "No time or distance threshold is given for when cutting back is too soon."
    }
   ],
   "links": [],
   "note": null
  },
  {
   "id": "3.5.2a",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "imperative (\"signal\", \"pull over\")",
   "text": "a driver towing a trailer SHOULD signal AND pull over WHEN the driver is holding up a line of traffic",
   "sources": [
    {
     "id": "m83",
     "quote": "If you are holding up a line of traffic, signal, pull over and let the other vehicles pass."
    }
   ],
   "flags": [],
   "links": [],
   "note": null
  },
  {
   "id": "3.5.2b",
   "type": "FACT",
   "force": null,
   "force_from": null,
   "text": "FACT fast-moving trucks and buses create a strong air disturbance behind them",
   "sources": [
    {
     "id": "m83",
     "quote": "Fast-moving trucks and buses create a strong air disturbance behind them."
    }
   ],
   "flags": [],
   "links": [],
   "note": null
  },
  {
   "id": "3.5.2c",
   "type": "FACT",
   "force": null,
   "force_from": null,
   "text": "FACT the wall of wind behind a large bus or truck that passes a driver towing a trailer may whip the trailer to the side, pushing it out of control",
   "sources": [
    {
     "id": "m83",
     "quote": "If a large bus or truck passes you, the wall of wind behind it may whip your trailer to the side, pushing it out of control."
    }
   ],
   "flags": [],
   "links": [],
   "note": null
  },
  {
   "id": "3.5.2d",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "imperative (\"do not brake\")",
   "text": "a driver towing a trailer SHOULD NOT brake WHEN the trailer is whipped to the side by the wind behind a passing large bus or truck",
   "sources": [
    {
     "id": "m83",
     "quote": "When you experience this, do not brake."
    }
   ],
   "flags": [],
   "links": [],
   "note": "The condition 'When you experience this' refers to the trailer being whipped to the side by the wind, as described in the previous sentence."
  },
  {
   "id": "3.5.2e",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "imperative (\"steer\")",
   "text": "a driver towing a trailer SHOULD [?carefully] steer the vehicle and trailer back into position WHEN the trailer is whipped to the side by the wind behind a passing large bus or truck",
   "sources": [
    {
     "id": "m83",
     "quote": "Carefully steer your vehicle and trailer back into position."
    }
   ],
   "flags": [
    {
     "code": "J",
     "span": "carefully",
     "note": "No specific steering technique or speed is defined."
    }
   ],
   "links": [],
   "note": null
  },
  {
   "id": "3.5.2f",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "text (\"may help\")",
   "text": "a driver towing a trailer MAY increase speed slightly WHEN the trailer is whipped to the side by the wind behind a passing large bus or truck",
   "sources": [
    {
     "id": "m83",
     "quote": "A slight increase in speed may help."
    }
   ],
   "flags": [
    {
     "code": "M",
     "span": "may help",
     "note": "The wording 'may help' is suggestive of advice rather than a legal permission, but 'may' is the only modal available for a non-prohibitive action option."
    }
   ],
   "links": [],
   "note": "The handbook suggests this as a helpful action, not a strict obligation or permission. 'MAY' is used to represent the option, with an M flag to note the advisory nature."
  }
 ]
}
